page.css:
/* =========================================================================
   Mi Painting & Maintenance : Location page design family (v4, clean mockup, notes in separate handoff)
   BRAND TOKENS verified from live-site computed CSS (2026-07-29)
   Red #FF0000 : Black/Charcoal #1E1E20 : White : Grey #F3F3F3
   ========================================================================= */
:root{
  --red:#FF0000;          /* primary brand red (sampled from buttons/splash) */
  --red-hover:#E00000;    /* button hover */
  --red-ink:#D50000;      /* derived deeper red for body links (AA on white) */
  --black:#141416;        /* headings */
  --charcoal:#1E1E20;     /* dark hero/section background (sampled) */
  --charcoal-900:#0E0E10; /* footer base */
  --ink:#2C2C2C;          /* body text (sampled) */
  --muted:#5C5C5C;
  --bg:#FFFFFF;
  --bg-alt:#F3F3F3;       /* light grey section band (sampled) */
  --line:#E6E6E6;
  --gold:#F5A623;         /* review stars (Google style) */
  --ok:#1E7B45;
  --radius:14px;
  --shadow:0 12px 34px rgba(20,20,22,.12);
  --shadow-sm:0 4px 14px rgba(20,20,22,.08);
  --container:1200px;
  --font:'Average Sans',system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
  --font-head:'Lexend Deca',system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);color:var(--ink);background:var(--bg);line-height:1.62;font-size:17px;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{color:var(--black);line-height:1.16;margin:0 0 .5em;font-weight:600;letter-spacing:-.01em;font-family:var(--font-head)}
.btn,.nav-links>li>a,.nav-phone,.eyebrow,.field label,.card h3,.step h3,.pillar h3,.review .rname,.faq summary,.partner-chip,footer.site h4,.card-link,.topbar,.trustbar .ti,.rating-summary .score{font-family:var(--font-head)}
h1{font-size:clamp(2rem,4.6vw,3.3rem)}
h2{font-size:clamp(1.6rem,3.2vw,2.4rem)}
h3{font-size:1.24rem}
p{margin:0 0 1rem}
a{color:var(--red-ink)}
img{max-width:100%;display:block}
.container{max-width:var(--container);margin:0 auto;padding:0 22px}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;text-transform:uppercase;letter-spacing:.12em;font-size:.78rem;font-weight:800;color:var(--red);margin-bottom:.7rem}
.eyebrow::before{content:"";width:26px;height:4px;border-radius:3px;background:var(--red)}
.center{text-align:center}
.center .eyebrow{justify-content:center}
.lead{font-size:1.14rem;color:var(--muted)}

/* Buttons */
.btn{display:inline-flex;align-items:center;gap:.55rem;font-weight:800;font-size:1.04rem;padding:.95rem 1.65rem;border-radius:999px;text-decoration:none;cursor:pointer;border:2px solid transparent;transition:transform .12s ease,background .15s ease}
.btn:focus-visible{outline:3px solid #ffb3b3;outline-offset:2px}
.btn-primary{background:var(--red);color:#fff}
.btn-primary:hover{background:var(--red-hover);transform:translateY(-1px)}
.btn-dark{background:var(--black);color:#fff}
.btn-dark:hover{background:#000;transform:translateY(-1px)}
.btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.55)}
.btn-ghost:hover{background:rgba(255,255,255,.12)}
.btn-outline{background:transparent;color:var(--black);border-color:var(--black)}
.btn-outline:hover{background:var(--black);color:#fff}
.btn-lg{padding:1.05rem 1.95rem;font-size:1.1rem}

.skip{position:absolute;left:-999px;top:0;background:#fff;color:var(--black);padding:.7rem 1.1rem;z-index:2000;border-radius:0 0 8px 0;font-weight:700}
.skip:focus{left:0}

/* Top bar */
.topbar{background:var(--black);color:#e7e7e9;font-size:.86rem}
.topbar .container{display:flex;justify-content:space-between;align-items:center;gap:1rem;min-height:38px;flex-wrap:wrap}
.topbar a{color:#fff;text-decoration:none}
.topbar .tb-left i{color:var(--red);margin-right:.35rem}
.topbar .tb-right{display:flex;gap:1.15rem;align-items:center}
.topbar .tb-right i{color:var(--red);margin-right:.3rem}
.topbar .sep{opacity:.35}

/* Header / nav */
header.site{position:sticky;top:0;z-index:1000;background:#fff;border-bottom:1px solid #ececec;box-shadow:0 2px 12px rgba(20,20,22,.06)}
.nav{display:flex;align-items:center;justify-content:space-between;gap:1rem;min-height:76px}
.brand{display:flex;align-items:center;text-decoration:none}
.brand img{height:52px;width:auto}
.nav-links{display:flex;align-items:center;gap:1.35rem;list-style:none;margin:0;padding:0}
.nav-links > li > a{color:var(--black);text-decoration:none;font-weight:700;font-size:.98rem;padding:.4rem 0}
.nav-links > li > a:hover{color:var(--red)}
.has-menu{position:relative}
.has-menu > a::after{content:"\f107";font-family:"Font Awesome 6 Free";font-weight:900;font-size:.75rem;margin-left:.35rem}
.submenu{position:absolute;top:calc(100% + 8px);left:0;background:#fff;border:1px solid #ececec;border-radius:12px;box-shadow:var(--shadow);padding:.5rem;min-width:250px;display:none;grid-template-columns:1fr 1fr;gap:.1rem;z-index:50}
.submenu a{display:block;padding:.5rem .7rem;border-radius:8px;text-decoration:none;color:var(--ink);font-size:.92rem;font-weight:600}
.submenu a:hover{background:#fff0f0;color:var(--red)}
.has-menu:hover .submenu,.has-menu:focus-within .submenu{display:grid}
.nav-cta{display:flex;align-items:center;gap:.7rem}
.nav-phone{display:inline-flex;align-items:center;gap:.5rem;font-weight:800;color:#fff;background:var(--red);text-decoration:none;font-size:1rem;padding:.6rem 1.05rem;border-radius:999px}
.nav-phone:hover{background:var(--red-hover)}
.hamburger{display:none;background:var(--black);color:#fff;border:0;width:46px;height:46px;border-radius:10px;font-size:1.2rem;cursor:pointer}

/* Hero */
.hero{background:var(--charcoal);color:#f2f2f3;position:relative;overflow:hidden}
.hero .container{display:grid;grid-template-columns:1.12fr .88fr;gap:2.4rem;padding-top:3.2rem;padding-bottom:3.4rem;align-items:center;position:relative;z-index:2}
.hero .breadcrumb{font-size:.85rem;color:#b9b9bd;margin-bottom:1rem}
.hero .breadcrumb a{color:#fff;text-decoration:none}
.hero .breadcrumb a:hover{text-decoration:underline}
.hero h1{color:#fff;margin-bottom:.7rem}
.hero .subhead{font-size:1.16rem;color:#d4d4d7;max-width:40ch;margin-bottom:1.4rem}
.eeat{display:flex;flex-wrap:wrap;gap:.55rem;margin:0 0 1.6rem;padding:0;list-style:none}
.eeat li{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);padding:.5rem .85rem;border-radius:999px;font-size:.9rem;font-weight:700;color:#fff}
.eeat li i{color:var(--red)}
.eeat li .stars{color:var(--gold)}
.hero-actions{display:flex;gap:.8rem;flex-wrap:wrap;align-items:center}
.trust-inline{margin-top:1.4rem;font-size:.9rem;color:#b9b9bd;display:flex;align-items:center;gap:.5rem}
.trust-inline i{color:var(--red)}
/* red paint splash motif */
.splash{position:absolute;right:-6%;top:50%;transform:translateY(-50%);width:60%;max-width:760px;z-index:1;opacity:.95;pointer-events:none}
.hero-media{position:relative;z-index:2}
.hero-media .imgph{min-height:360px;border-radius:230px 230px 18px 18px;background:repeating-linear-gradient(135deg,rgba(255,255,255,.10) 0 14px,rgba(255,255,255,.04) 14px 28px);border:2px dashed rgba(255,255,255,.4);color:#fff}
.hero-media .imgph .ph-meta{color:#d9d9dc}

/* Trust bar */
.trustbar{background:#fff;border-bottom:1px solid #efefef}
.trustbar .container{display:flex;flex-wrap:wrap;justify-content:space-between;gap:1rem;padding:1.1rem 22px}
.trustbar .ti{display:flex;align-items:center;gap:.6rem;font-weight:700;color:var(--black);font-size:.95rem}
.trustbar .ti i{color:var(--red);font-size:1.15rem}
.trustbar .ti .stars{color:var(--gold)}

/* Sections */
section{padding:4rem 0}
.section-alt{background:var(--bg-alt)}
.section-dark{background:var(--charcoal);color:#dcdcde;position:relative;overflow:hidden}
.section-dark h2,.section-dark h3{color:#fff}
.section-dark .eyebrow{color:#ff6a6a}
.section-dark .eyebrow::before{background:var(--red)}
.section-head{max-width:780px;margin:0 auto 2.4rem;text-align:center}
.split{display:grid;grid-template-columns:1fr 1fr;gap:2.6rem;align-items:center}
.split.reverse .split-media{order:2}
.prose h2{margin-bottom:.7rem}
.ticklist{list-style:none;padding:0;margin:1rem 0 0;display:grid;gap:.6rem}
.ticklist li{display:flex;gap:.65rem;align-items:flex-start;font-weight:600;color:var(--ink)}
.ticklist li i{color:var(--red);margin-top:.28rem}

/* Image placeholder */
.imgph{position:relative;border-radius:var(--radius);overflow:hidden;background:repeating-linear-gradient(135deg,#f0f0f0 0 14px,#e7e7e7 14px 28px);border:2px dashed #c2c2c2;display:flex;align-items:center;justify-content:center;min-height:260px;color:var(--black)}
.imgph .ph-inner{text-align:center;padding:1rem;max-width:90%}
.imgph .ph-tag{display:inline-block;background:var(--red);color:#fff;font-size:.7rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;padding:.3rem .6rem;border-radius:6px;margin-bottom:.55rem}
.imgph .ph-purpose{font-weight:700;font-size:.95rem;margin-bottom:.25rem}
.imgph .ph-meta{font-size:.78rem;color:var(--muted);font-weight:600}
.imgph.tall{min-height:100%}

/* Service cards */
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:1.1rem}
.card{background:#fff;border:1px solid #ececec;border-radius:var(--radius);padding:1.4rem 1.25rem;box-shadow:var(--shadow-sm);transition:transform .14s ease,box-shadow .14s ease,border-color .14s ease;display:flex;flex-direction:column}
.card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:#ffc9c9}
.card .ic{width:52px;height:52px;border-radius:12px;background:#fff0f0;color:var(--red);display:flex;align-items:center;justify-content:center;font-size:1.35rem;margin-bottom:.9rem}
.card h3{font-size:1.1rem;margin-bottom:.4rem}
.card p{font-size:.93rem;color:var(--muted);margin-bottom:1rem;flex:1}
.card .card-link{font-weight:800;color:var(--red-ink);text-decoration:none;font-size:.92rem;display:inline-flex;align-items:center;gap:.4rem}
.card .card-link:hover{gap:.6rem}

/* Pillars */
.pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:1.4rem}
.pillar{background:#fff;border-radius:var(--radius);padding:1.6rem;box-shadow:var(--shadow-sm);border-top:4px solid var(--red)}
.pillar i{font-size:1.6rem;color:var(--red);margin-bottom:.6rem}
.pillar h3{font-size:1.14rem}
.pillar p{font-size:.95rem;color:var(--muted);margin:0}

/* Process */
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:1.2rem}
.step{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.14);border-radius:var(--radius);padding:1.5rem 1.3rem}
.step .num{width:44px;height:44px;border-radius:50%;background:var(--red);color:#fff;font-weight:800;font-size:1.15rem;display:flex;align-items:center;justify-content:center;margin-bottom:.8rem}
.step h3{color:#fff;font-size:1.08rem;margin-bottom:.3rem}
.step p{color:#c7c7ca;font-size:.9rem;margin:0}

/* Coverage */
.coverage{background:#fff;border:1px solid #ececec;border-radius:var(--radius);padding:1.8rem;box-shadow:var(--shadow-sm)}
.suburb-grid{columns:4;column-gap:1.4rem;margin:1rem 0 0}
.suburb-grid span{display:flex;align-items:center;gap:.5rem;padding:.28rem 0;font-weight:600;color:var(--ink);font-size:.95rem;break-inside:avoid}
.suburb-grid span i{color:var(--red);font-size:.7rem}
.coverage-note{margin-top:1.3rem;padding:1rem 1.15rem;background:#fff0f0;border:1px solid #ffd4d4;border-radius:10px;font-weight:600;color:var(--black);display:flex;align-items:center;gap:.7rem;flex-wrap:wrap}
.coverage-note i{color:var(--red)}
.partners{display:flex;flex-wrap:wrap;gap:1rem;justify-content:center;align-items:center;margin-top:1.5rem}
.partner-chip{background:#fff;border:1px solid #e6e6e6;border-radius:10px;padding:.75rem 1.3rem;font-weight:800;color:var(--black);box-shadow:var(--shadow-sm)}

/* Reviews */
.rating-summary{display:flex;align-items:center;gap:1.1rem;justify-content:center;flex-wrap:wrap;margin-bottom:1.8rem}
.rating-summary .gwrap{display:flex;align-items:center;gap:.8rem;background:#fff;border:1px solid #ececec;border-radius:14px;padding:1rem 1.4rem;box-shadow:var(--shadow-sm)}
.rating-summary .score{font-size:2.4rem;font-weight:800;color:var(--black);line-height:1}
.rating-summary .stars{color:var(--gold);font-size:1.15rem}
.rating-summary .rs-meta{font-size:.9rem;color:var(--muted);font-weight:600}
.review-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1.2rem;max-width:900px;margin:0 auto}
.review{background:#fff;border:1px solid #ececec;border-radius:var(--radius);padding:1.5rem;box-shadow:var(--shadow-sm)}
.review .rtop{display:flex;justify-content:space-between;align-items:center;margin-bottom:.6rem}
.review .stars{color:var(--gold)}
.review .gicon{color:#4285F4;font-size:1.1rem}
.review .rtext{color:var(--ink);font-size:.98rem}
.review .rname{margin-top:.9rem;font-weight:800;color:var(--black);font-size:.92rem}
.review .rname span{display:block;font-weight:600;color:var(--muted);font-size:.8rem}

/* FAQ */
.faq{max-width:860px;margin:0 auto}
.faq details{background:#fff;border:1px solid #ececec;border-radius:12px;margin-bottom:.8rem;box-shadow:var(--shadow-sm);overflow:hidden}
.faq summary{cursor:pointer;padding:1.1rem 1.3rem;font-weight:800;color:var(--black);list-style:none;display:flex;justify-content:space-between;align-items:center;gap:1rem;font-size:1.02rem}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"\f067";font-family:"Font Awesome 6 Free";font-weight:900;color:var(--red);font-size:.85rem;flex:none}
.faq details[open] summary::after{content:"\f068"}
.faq .faq-body{padding:0 1.3rem 1.2rem;color:var(--muted)}

/* Final CTA */
.cta-band{background:var(--charcoal);color:#fff;text-align:center;position:relative;overflow:hidden}
.cta-band h2{color:#fff}
.cta-band p{color:#d4d4d7;max-width:60ch;margin:0 auto 1.6rem;font-size:1.12rem}
.cta-actions{display:flex;gap:.9rem;justify-content:center;flex-wrap:wrap;position:relative;z-index:2}
.cta-band .splash{opacity:.9}

/* Footer */
footer.site{background:var(--charcoal-900);color:#b4b4b8;font-size:.93rem}
.footer-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.1fr;gap:2rem;padding:3.2rem 0 2.4rem}
footer.site h4{color:#fff;font-size:1rem;margin-bottom:1rem;text-transform:uppercase;letter-spacing:.06em}
footer.site a{color:#c9c9cc;text-decoration:none}
footer.site a:hover{color:#fff;text-decoration:underline}
.footer-brand .logo-plate{display:inline-block;background:#fff;padding:.7rem .9rem;border-radius:12px;margin-bottom:1rem}
.footer-brand .logo-plate img{height:50px;width:auto}
.footer-brand p{color:#9c9ca0;font-size:.9rem;max-width:34ch}
.f-contact{padding:0;margin:0}
.f-contact li{display:flex;gap:.6rem;align-items:flex-start;margin-bottom:.6rem;list-style:none}
.f-contact i{color:var(--red);margin-top:.25rem;width:16px;text-align:center}
.f-list{list-style:none;padding:0;margin:0;display:grid;gap:.5rem}
.socials{display:flex;gap:.55rem;margin-top:1.1rem;flex-wrap:wrap}
.socials a{width:40px;height:40px;border-radius:9px;background:rgba(255,255,255,.08);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.05rem;transition:background .15s ease}
.socials a:hover{background:var(--red)}
.footer-bottom{border-top:1px solid rgba(255,255,255,.12);padding:1.3rem 0;display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.85rem;color:#8a8a8e}
.footer-bottom a{color:#b4b4b8}

/* Quote form card */
.quote-card{background:#fff;color:var(--ink);border-radius:18px;box-shadow:var(--shadow);padding:1.5rem;border:1px solid #ececec}
.quote-card h3{font-size:1.35rem;margin-bottom:.25rem}
.quote-card .qc-sub{color:var(--muted);font-size:.92rem;margin-bottom:1rem}
.field{margin-bottom:.7rem}
.field label{display:block;font-size:.82rem;font-weight:700;color:var(--black);margin-bottom:.28rem}
.field label .req{color:var(--red)}
.field input,.field select,.field textarea{width:100%;padding:.72rem .8rem;border:1.5px solid #d8d8d8;border-radius:10px;font-size:.97rem;font-family:inherit;color:var(--ink);background:#fff}
.field input:focus,.field select:focus,.field textarea:focus{outline:0;border-color:var(--red);box-shadow:0 0 0 3px rgba(252,0,0,.14)}
.field textarea{resize:vertical;min-height:64px}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form-note{font-size:.78rem;color:var(--muted);margin:.5rem 0 0}
.form-status{display:none;margin-top:.7rem;padding:.7rem .8rem;border-radius:8px;font-size:.9rem;font-weight:600}
.form-status.show{display:block}
.form-status.test{background:#fff4e5;border:1px solid #f4c88a;color:#8a5a12}

/* Production switch: remove body class 'preview' to hide image-placeholder labels */
body:not(.preview) .imgph .ph-tag,body:not(.preview) .imgph .ph-meta{display:none}

@media(max-width:1024px){
  .cards{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:repeat(2,1fr)}
  .suburb-grid{columns:3}.footer-top{grid-template-columns:1fr 1fr}
  .hero .container{grid-template-columns:1fr;gap:1.8rem}.hero-media .imgph{display:none}.splash{opacity:.5;right:-20%}
}
@media(max-width:820px){
  .nav-links,.nav-phone .np-label{display:none}.hamburger{display:inline-flex}
  .nav-links.open{display:flex;position:absolute;top:76px;left:0;right:0;flex-direction:column;background:#fff;padding:1rem;gap:.2rem;border-bottom:1px solid #ececec;box-shadow:var(--shadow)}
  .nav-links.open > li{width:100%}.nav-links.open > li > a{display:block;padding:.8rem .4rem;border-bottom:1px solid #f2f2f2}
  .submenu{position:static;display:grid;box-shadow:none;border:0;padding:.2rem 0 .6rem 1rem;grid-template-columns:1fr}.has-menu > a::after{display:none}
  .split{grid-template-columns:1fr;gap:1.5rem}.split.reverse .split-media{order:0}
  .pillars,.review-grid{grid-template-columns:1fr}.suburb-grid{columns:2}
}
@media(max-width:560px){
  .cards,.steps,.footer-top{grid-template-columns:1fr}.topbar .tb-left{display:none}body{font-size:16px}
}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important;animation:none!important}}


.suburb-grid a{display:flex;align-items:center;gap:.5rem;padding:.28rem 0;font-weight:700;color:var(--red-ink);text-decoration:none;break-inside:avoid;font-size:.95rem}.suburb-grid a:hover{color:var(--red);text-decoration:underline}.suburb-grid a i,.suburb-grid span i{color:var(--red);font-size:.7rem}.also-serve{margin-top:1.1rem;color:var(--muted);font-size:.95rem;line-height:1.7}.also-serve strong{color:var(--black)}
